
ALTER TABLE public.services ADD COLUMN IF NOT EXISTS keywords text;

-- 1. Асфальтирование
UPDATE public.services SET
  short_description = 'Асфальтирование территорий, дорог, дворов и парковок в Перми и Пермском крае под ключ. Бесплатный замер, договор, гарантия 3 года.',
  description = E'Асфальтирование в Перми и Пермском крае — комплексные работы по укладке асфальта на территории любой сложности: дворы многоквартирных домов, парковки торговых центров, подъездные пути к складам, частные участки, дороги и тротуары.\n\nЧто входит в услугу:\n• Бесплатный выезд инженера и точные замеры\n• Геодезическая разбивка участка и согласование уклонов для отвода воды\n• Корчевание и снятие растительного слоя, подготовка котлована\n• Устройство щебёночного основания с послойным уплотнением виброкатком\n• Укладка нижнего слоя асфальтобетона (марка II, тип Б)\n• Финишная укладка верхнего слоя горячим способом (марка I, тип А)\n• Прикатка катками тяжёлого и среднего класса для нужной плотности\n• Установка бордюрного камня, организация ливневых лотков и решёток\n\nЦена асфальтирования в Перми зависит от площади, толщины слоя (5, 7 или 10 см) и состояния основания. Базовая стоимость — от 1 500 ₽ за м². При объёме от 500 м² предоставляем оптовую скидку. Работаем с физическими и юридическими лицами, заключаем официальный договор, выдаём акты и счета-фактуры с НДС.\n\nГарантия на работы — 3 года. Используем асфальтобетонную смесь с заводов Пермского края (ГОСТ 9128-2013) и собственный парк техники: асфальтоукладчики Vögele, катки Hamm и Bomag, самосвалы КАМАЗ. Выполняем заказы в Перми, Краснокамске, Березниках, Соликамске, Чайковском, Кунгуре, Лысьве, Чусовом и других населённых пунктах региона.',
  keywords = 'асфальтирование пермь, асфальтирование цена за м2 пермь, асфальтирование двора, асфальтирование парковки, асфальтирование дорог, укладка асфальта пермь, асфальтировщики пермь, асфальтирование под ключ, асфальтирование территории, асфальтирование пермский край, асфальтобетон пермь'
WHERE slug = 'asfaltirovanie';

-- 2. Укладка тротуарной плитки
UPDATE public.services SET
  short_description = 'Укладка тротуарной плитки в Перми: брусчатка, вибропрессованная и гранитная плитка. Дорожки, дворы, парковки. Гарантия 3 года.',
  description = E'Укладка тротуарной плитки в Перми и Пермском крае — благоустройство пешеходных зон, дворов частных домов, придомовых территорий, парковок и подъездных дорожек. Работаем с любой плиткой: вибролитой и вибропрессованной, гранитной брусчаткой, клинкерным кирпичом, плиткой «Старый город», «Кирпичик», «Английский булыжник».\n\nЭтапы работ:\n• Бесплатный замер и согласование схемы укладки (рисунок, цвета, направление)\n• Снятие старого покрытия и грунта на глубину 25–35 см\n• Устройство щебёночной подушки с уплотнением виброплитой\n• Установка бордюров и водоотводных лотков по уровню\n• Укладка геотекстиля для предотвращения прорастания травы\n• Сухая цементно-песчаная смесь под плитку\n• Раскладка плитки с резкой по периметру алмазным диском\n• Затирка швов кварцевым песком или полимерной затиркой\n\nЦена укладки тротуарной плитки в Перми — от 850 ₽ за м² (работа) или от 2 200 ₽ за м² с материалом. Расчёт зависит от типа плитки, сложности рисунка, площади и состояния основания. Принимаем оплату по безналу с НДС, работаем с управляющими компаниями, ТСЖ, юридическими лицами.\n\nГарантия — 3 года. Используем плитку проверенных пермских и российских заводов (Выбор, Steingot, БРАЕР). Соблюдаем СП 82.13330.2016 «Благоустройство территорий».',
  keywords = 'укладка тротуарной плитки пермь, тротуарная плитка цена пермь, укладка брусчатки пермь, плиточник пермь, тротуарная плитка под ключ, благоустройство двора плиткой, гранитная брусчатка пермь, вибропрессованная плитка пермь, дорожки из плитки, мощение тротуарной плиткой'
WHERE slug = 'ukladka-plitki';

-- 3. Демонтаж
UPDATE public.services SET
  short_description = 'Демонтаж зданий, сооружений, фундаментов и старых покрытий в Перми. Своя техника, вывоз мусора, утилизация по ГОСТ.',
  description = E'Демонтаж зданий и сооружений в Перми и Пермском крае — снос ветхих построек, промышленных цехов, ангаров, гаражей, дачных домов, бань и хозблоков. Демонтируем железобетонные фундаменты, кирпичные стены, металлоконструкции, старые асфальтовые и бетонные покрытия.\n\nЧто включает услуга:\n• Бесплатный выезд и оценка объекта, расчёт сметы\n• Получение разрешительной документации (при необходимости)\n• Отключение коммуникаций — электричество, газ, вода\n• Поэтапный механизированный или ручной демонтаж\n• Резка железобетона алмазными дисками и канатами\n• Дробление бетона гидромолотом на экскаваторе\n• Сортировка и вывоз строительного мусора\n• Утилизация отходов на лицензированных полигонах Пермского края\n• Планировка площадки после демонтажа\n\nЦена демонтажа в Перми — от 450 ₽ за м³ железобетона, от 350 ₽ за м² кирпичной кладки, от 220 ₽ за м² старого асфальта. Стоимость зависит от объёма, материала конструкций, удалённости объекта и необходимости вывоза. Принимаем заказы от частных лиц и организаций, заключаем договор с фиксированной сметой.\n\nСвой парк техники: экскаваторы JCB и Hitachi с гидромолотами, фронтальные погрузчики, самосвалы 10 и 20 тонн, краны-манипуляторы. Соблюдаем СП 325.1325800.2017 и требования техники безопасности.',
  keywords = 'демонтаж пермь, снос здания пермь, демонтаж зданий цена, демонтаж фундамента пермь, снос дома пермь, демонтаж железобетона, демонтаж кирпичных стен, демонтаж старого асфальта, демонтаж сооружений, снос ветхих построек пермь'
WHERE slug = 'demontazh';

-- 4. Земляные работы
UPDATE public.services SET
  short_description = 'Земляные работы в Перми: разработка котлованов, рытьё траншей, планировка участка, выемка грунта, обратная засыпка.',
  description = E'Земляные работы в Перми и Пермском крае — комплексные услуги экскаваторной техники для строительных площадок, частных участков и промышленных объектов. Выполняем разработку котлованов под фундаменты, рытьё траншей для коммуникаций, планировку и выравнивание территорий, выемку и перемещение грунта, обратную засыпку с послойным уплотнением.\n\nВиды работ:\n• Котлованы под ленточные, плитные и свайные фундаменты\n• Траншеи под водопровод, канализацию, газопровод, электрокабель\n• Корчевание пней и расчистка участков от поросли\n• Срезка плодородного слоя с буртовкой\n• Вертикальная планировка с устройством уклонов\n• Устройство дренажных систем и ливневой канализации\n• Обратная засыпка с уплотнением виброплитой и катком\n• Погрузка грунта в самосвалы и вывоз на полигон\n\nЦена земляных работ в Перми — от 380 ₽ за м³ разработки грунта механизированным способом, от 1 200 ₽ за м³ ручной разработки в стеснённых условиях. Работаем с грунтами всех групп: песок, супесь, суглинок, глина, скальные породы (рыхление гидромолотом).\n\nПарк техники: гусеничные экскаваторы Hitachi ZX200, колёсные экскаваторы JCB JS160W, мини-экскаваторы для узких мест, бульдозеры, грейдеры, виброплиты Wacker Neuson. Выезжаем по всему Пермскому краю с собственным тралом.',
  keywords = 'земляные работы пермь, разработка котлована пермь, услуги экскаватора пермь, рытьё траншей пермь, планировка участка пермь, выемка грунта, земельные работы цена, разработка грунта экскаватором, обратная засыпка, корчевание участка пермь'
WHERE slug = 'zemlyanye-raboty';

-- 5. Нерудные материалы
UPDATE public.services SET
  short_description = 'Доставка нерудных материалов в Перми: щебень, песок, ПГС, отсев, скальный грунт, чернозём. Самосвалы 10–25 тонн.',
  description = E'Доставка нерудных материалов в Перми и Пермском крае самосвалами от 10 до 25 тонн. Поставляем сертифицированные стройматериалы напрямую с карьеров без посредников — отсюда выгодная цена и проверенное качество.\n\nАссортимент:\n• Щебень гранитный фракций 5–20, 20–40, 40–70 мм (М1200, М1400)\n• Щебень известняковый фракций 5–20, 20–40 мм\n• Гравий речной мытый 5–20, 20–40 мм\n• Песок строительный карьерный (Мкр 1,5–2,5)\n• Песок речной мытый для бетонов и штукатурки\n• Песчано-гравийная смесь (ПГС, ОПГС)\n• Отсев гранитный и известняковый 0–5 мм\n• Скальный грунт для отсыпки оснований\n• Чернозём и плодородный грунт для благоустройства\n• Глина для гидроизоляции\n\nЦена с доставкой по Перми — от 850 ₽ за тонну песка, от 1 100 ₽ за тонну щебня. Возможна доставка маленькими партиями (от 5 тонн) и крупным тоннажем (полуприцеп 25 тонн). Расчёт за наличный и безналичный расчёт, документы для бухгалтерии — счёт, ТТН, паспорт качества.\n\nСвой парк самосвалов КАМАЗ-65115, КАМАЗ-6520 и Scania с системой контроля веса. Доставка в течение 1–2 дней по Перми, Пермскому краю и соседним регионам.',
  keywords = 'щебень с доставкой пермь, песок с доставкой пермь, нерудные материалы пермь, ПГС пермь, отсев пермь купить, щебень гранитный пермь, чернозём пермь доставка, скальный грунт пермь, доставка щебня самосвалом, песок строительный цена'
WHERE slug = 'nerudnye-materialy';

-- 6. Аренда спецтехники
UPDATE public.services SET
  short_description = 'Аренда спецтехники в Перми с водителем: экскаваторы, погрузчики, самосвалы, катки, бульдозеры, манипуляторы.',
  description = E'Аренда спецтехники в Перми и Пермском крае с опытными машинистами и сменным оборудованием. Свой парк техники в исправном состоянии, проходит ежедневный осмотр механиков. Работаем посменно (8–11 часов) и помесячно, выезд по всему региону.\n\nДоступная техника:\n• Гусеничные экскаваторы Hitachi ZX200, Komatsu PC200 — объём ковша 1,0 м³\n• Колёсные экскаваторы JCB JS160W — для городских условий\n• Мини-экскаваторы Bobcat E26 — для узких мест и теплиц\n• Экскаваторы-погрузчики JCB 3CX и Caterpillar 434F\n• Фронтальные погрузчики XCMG, SDLG (ковш 3 м³)\n• Самосвалы КАМАЗ-65115 (10 т) и КАМАЗ-6520 (20 т)\n• Катки дорожные Hamm HD12, Bomag BW213 (виброкатки)\n• Бульдозеры Shantui SD16, Caterpillar D6\n• Краны-манипуляторы 5, 7 и 10 тонн\n• Виброплиты, виброкатки ручные для уплотнения\n• Гидромолоты для дробления железобетона\n\nЦена аренды в Перми — от 1 800 ₽/час за мини-экскаватор, от 2 500 ₽/час за полноразмерный экскаватор, от 3 200 ₽/час за манипулятор. Минимальный заказ — смена 8 часов. Доставка техники на трале по Перми и Пермскому краю. Заключаем договор аренды, выдаём акты выполненных работ.',
  keywords = 'аренда спецтехники пермь, аренда экскаватора пермь, аренда погрузчика пермь, аренда самосвала пермь, аренда катка пермь, аренда бульдозера пермь, аренда манипулятора пермь, услуги экскаватора цена час, аренда мини экскаватора, спецтехника в аренду пермский край'
WHERE slug = 'arenda-spectexniki';

-- 7. Уборка и вывоз снега
UPDATE public.services SET
  short_description = 'Уборка и вывоз снега в Перми с территорий, дворов, парковок. Круглосуточно, в течение 2 часов. Договор на сезон.',
  description = E'Уборка и вывоз снега в Перми — механизированная очистка территорий, парковок, дворов, въездов на склады, дорог промышленных предприятий, торговых центров и автостоянок. Работаем круглосуточно в зимний сезон, реагируем на заявку в течение 2 часов.\n\nЧто делаем:\n• Сдвигание снега тракторами и фронтальными погрузчиками\n• Очистка пешеходных зон вручную и снегоуборочной техникой\n• Скалывание наледи и обработка противогололёдными материалами\n• Погрузка снега в самосвалы фронтальным погрузчиком\n• Вывоз снега на лицензированные снегоплавильные пункты Перми\n• Очистка крыш от снега и наледи (с допуском на высоту)\n• Посыпка территорий песком, солью и фрикционной смесью\n\nЦена уборки снега в Перми — от 1 500 ₽/час трактор МТЗ, от 2 200 ₽/час фронтальный погрузчик, от 4 500 ₽ за рейс самосвала 10 т. Заключаем сезонные договоры с УК, ТСЖ, торговыми центрами и предприятиями — фиксируем тариф на всю зиму. Работаем по безналу с НДС, выдаём акты и счета-фактуры.\n\nСвой парк зимней техники: тракторы МТЗ-82 с щёткой и отвалом, погрузчики Bobcat S630, самосвалы КАМАЗ, машины посыпки солью. Закреплённая бригада за объектом, контроль через GPS.',
  keywords = 'уборка снега пермь, вывоз снега пермь, уборка территории от снега, расчистка снега пермь, вывоз снега цена, очистка крыш от снега пермь, снегоуборочные работы пермь, уборка двора от снега, посыпка солью пермь, обработка против гололёда'
WHERE slug = 'vyvoz-snega';

-- 8. Вывоз мусора
UPDATE public.services SET
  short_description = 'Вывоз строительного и крупногабаритного мусора в Перми. Контейнеры 8, 20, 27 м³. Утилизация по договору.',
  description = E'Вывоз строительного и крупногабаритного мусора в Перми и Пермском крае — после ремонта квартир, демонтажа, строительства, благоустройства. Предоставляем контейнеры объёмом 8, 20 и 27 м³ с доставкой и установкой на объекте, забираем по мере наполнения.\n\nКакой мусор вывозим:\n• Строительный мусор после ремонта (бетон, кирпич, штукатурка, плитка, гипсокартон)\n• Древесные отходы — доски, мебель, поддоны, ветки\n• Грунт и излишки земли с участка\n• Старый асфальт и бетонные плиты\n• Металлолом и металлоконструкции\n• Шифер и старая кровля (по отдельному договору)\n• Крупногабаритные отходы (мебель, бытовая техника)\n• Промышленные отходы 4–5 классов опасности\n\nЦена вывоза мусора в Перми — от 5 800 ₽ за бункер 8 м³, от 9 500 ₽ за 20 м³, от 12 000 ₽ за 27 м³. В стоимость входит доставка контейнера, аренда на 1–3 дня, погрузка-разгрузка, утилизация на лицензированном полигоне с выдачей талонов. Работаем по безналу с НДС, заключаем разовые и долгосрочные договоры с организациями.\n\nИмеем лицензию на обращение с отходами IV–V класса опасности. Контейнеры доставляем мультилифтом, выезжаем по Перми и Пермскому краю в течение 24 часов.',
  keywords = 'вывоз мусора пермь, вывоз строительного мусора пермь, контейнер для мусора пермь, аренда бункера пермь, вывоз мусора цена пермь, вывоз грунта пермь, вывоз крупногабаритного мусора, вывоз мусора после ремонта, бункер 8 м3 пермь, вывоз мусора с лицензией'
WHERE slug = 'vyvoz-musora';

-- 9. Кронирование
UPDATE public.services SET
  short_description = 'Кронирование, обрезка и спил деревьев в Перми. Удаление аварийных деревьев. Альпинисты, автовышка, дробление пней.',
  description = E'Кронирование, обрезка и удаление деревьев в Перми и Пермском крае — профессиональные арбористические работы для частных территорий, садов, парков, предприятий, ТСЖ и муниципальных объектов. Спиливаем аварийные и сухостойные деревья, удаляем пни, формируем кроны для здорового роста.\n\nВиды работ:\n• Кронирование — формирующая, санитарная и омолаживающая обрезка\n• Удаление сухих и больных ветвей\n• Понижение высоты дерева для безопасности\n• Удаление аварийных деревьев целиком (со связкой и валкой)\n• Спил деревьев в стеснённых условиях (промышленный альпинизм, верёвочная техника)\n• Удаление деревьев с автовышки (от 28 до 45 м)\n• Корчевание пней механизированным способом или дробление фрезой\n• Вывоз веток, стволов, древесных отходов\n• Лечение ран и обработка срезов садовым варом\n\nЦена обрезки деревьев в Перми — от 2 500 ₽ за дерево высотой до 5 м, от 6 000 ₽ за высотные работы (выше 10 м), от 1 800 ₽ за корчевание пня. Имеем порубочные билеты при работе на муниципальной территории, согласуем все разрешения с управлением благоустройства Перми.\n\nБригада сертифицированных арбористов с допусками к промышленному альпинизму. Используем профессиональные пилы STIHL, верёвочное снаряжение Petzl, автовышки 22–45 м, дробилки веток для измельчения на месте.',
